def account_state_rows(
    chain: list[Block], initial_balance: int
) -> list[tuple[str, int, list[str]]]:
    """Confirmed account-state rows ordered by ascending account id.

    Only confirmed blocks contribute, so the result is independent of any
    pending tip block. Each row is ``(account, confirmed_balance, T)``
    where ``T`` is the account's confirmed transaction ids in their
    original on-chain order.
    """
    activity: dict[str, dict] = {}
    for block in chain:
        if block.status != STATUS_CONFIRMED:
            continue
        for tx in block.transactions:
            for account in (tx.sender, tx.recipient):
                entry = activity.setdefault(
                    account, {"sent": 0, "received": 0, "transactions": []}
                )
                entry["transactions"].append(tx.tx_id)
            activity[tx.sender]["sent"] += tx.amount
            activity[tx.recipient]["received"] += tx.amount
    return [
        (
            account,
            initial_balance
            + activity[account]["received"]
            - activity[account]["sent"],
            list(activity[account]["transactions"]),
        )
        for account in sorted(activity)
    ]

def state_root_for(
    self, chain: list[Block], initial_balance: int
) -> tuple[str, list[str]]:
    """Compute ``(state_root, leaves)`` for confirmed accounts in ascending
    account order. The empty account set shares the empty Merkle root.
    """
    leaves = [
        crypto.account_state_leaf(account, balance, transactions)
        for account, balance, transactions in self.account_state_rows(
            chain, initial_balance
        )
    ]
    return crypto.account_state_root(leaves), leaves

# -- deferred persistence (uniform Idempotency-Key support) -------------

def begin_persistence(self) -> None:
    """Enter deferred-persistence mode for one idempotent request.

    While active, every :meth:`save` is a no-op: no temp snapshot is
    written, nothing is promoted and the in-memory generation does not
    advance. :meth:`commit_persistence` then performs exactly one real
    atomic write carrying the business change, its audit events and the
    idempotency record together. Caller must hold the store lock.
    """
    self._persist_deferred = True
    self._deferred_rollback = []

def defer_rollback(self, callback) -> None:
    """Register a best-effort undo for an external-file write made while
    persistence is deferred (the managed history signer log uses this so a
    failed final snapshot restores its original bytes)."""
    self._deferred_rollback.append(callback)

def commit_persistence(self, idempotency_entry: dict | None = None) -> None:
    """Leave deferred mode and perform the single real atomic write.

    When ``idempotency_entry`` is given it is installed first (keyed by its
    ``key``), so the write that publishes the business change is the same
    write that publishes the idempotency record. Raises (leaving deferred
    mode engaged, with registered rollback callbacks already run by the
    caller's snapshot) on failure.
    """
    self._persist_deferred = False
    if idempotency_entry is not None:
        self.idempotency[idempotency_entry["key"]] = {
            field: idempotency_entry[field]

def list_audit_events(self, params: dict) -> tuple[int, dict]:
    """GET /v1/audit/events — paginated append-only audit log.

    Filters ``source`` and ``kind`` are AND-combined; ``limit`` defaults
    to 50 and must be 1-200, ``cursor`` defaults to 0. Numeric values
    must be plain decimals without leading zeros. Events are ordered by
    their ascending ``event_id``; ``cursor == total`` returns an empty
    page, ``cursor > total`` returns 400.
    """
    source = params.get("source")
    if source is not None and (not isinstance(source, str) or not source):
        return 400, {"error": "source must be a non-empty string"}
    kind = params.get("kind")
    if kind is not None and (not isinstance(kind, str) or not kind):
        return 400, {"error": "kind must be a non-empty string"}
    limit = self.AUDIT_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.AUDIT_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        # Sweep expired syncs first so their expiry events are visible on
        # the same page that observes the removal.
        self._prune_expired_syncs()
        items = [
            dict(event)
            for event in self.store.audit_events
            if (source is None or event.get("source") == source)
            and (kind is None or event.get("kind") == kind)
        ]
    # Events are stored in ascending event_id order; filtering preserves it.
    total = len(items)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    page = items[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    return 200, {"items": page, "total": total, "next_cursor": next_cursor}

def export_audit_events(self, params: dict) -> tuple[int, dict]:
    """GET /v1/audit/export — hash-anchored export page for offline checks.

    Pagination is identical to ``GET /v1/audit/events`` for the *whole*
    log (no source/kind filters — an offline verifier replays every
    event): ``limit`` defaults to 50 and must be 1-200, ``cursor``
    defaults to 0; both must be plain decimals without leading zeros.
    Items are the events in ascending ``event_id``, each carrying its
    ``prev_hash``/``event_hash`` links. The response additionally
    contains:

    * ``anchor_hash`` — the hash immediately preceding the page's first
      event (64 zeroes at cursor 0; the head at cursor == total);
    * ``checkpoint`` — the current ``{event_id, event_hash}`` log head
      (``{0, "0"*64}`` for an empty log), included on every page;
    * ``checkpoint_auth`` — ``{key_version, signature}`` binding that
      checkpoint (and the genesis anchor) under the current audit signer;
      the same envelope is returned on every page of one export.

    ``cursor == total`` returns an empty last page (its anchor is the log
    head so the final page matches the checkpoint); ``cursor > total`` is
    400.

    The optional paired parameters ``checkpoint_event_id`` (a
    non-negative ASCII decimal without leading zeros) and
    ``checkpoint_hash`` (64 lowercase hex) pin the export to an explicit
    audit-chain prefix instead of the moving head. Both must appear
    together; a lone, repeated or malformed parameter is 400
    ``{"error": "input"}``. The pinned event id must already exist on the
    persisted chain with exactly that hash — event id 0 pins the empty
    prefix, whose hash is 64 zeroes — otherwise 409
    ``{"error": "checkpoint_conflict"}`` and nothing is persisted. A
    pinned export pages only the prefix: ``total`` is the pinned event
    id, ``checkpoint`` is exactly the requested
    ``{event_id, event_hash}`` and ``checkpoint_auth`` is signed by the
    newest signer activated at or before the checkpoint, so later
    appends, ledger changes and key rotations never alter the pinned
    pages.
    """
    limit = self.AUDIT_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.AUDIT_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed
    raw_checkpoint_id = params.get("checkpoint_event_id")
    raw_checkpoint_hash = params.get("checkpoint_hash")
    if (raw_checkpoint_id is None) != (raw_checkpoint_hash is None):
        # The pin is a pair: one half without the other is an input error.
        return 400, {"error": "input"}
    pinned = None
    if raw_checkpoint_id is not None:
        pinned_id = _parse_ascii_decimal(raw_checkpoint_id)
        if pinned_id is None or not crypto.is_hex64(raw_checkpoint_hash):
            return 400, {"error": "input"}
        pinned = {"event_id": pinned_id, "event_hash": raw_checkpoint_hash}

    with self.store.lock:
        # Sweep due expiries first, exactly like /v1/audit/events, so the
        # exported checkpoint and log never lag a durable expiry.
        self._prune_expired_syncs()
        events = self.store.audit_events
        if pinned is not None:
            # Validate the pin against the persisted chain: the event id
            # must have been reached and its recorded hash must match
            # exactly. A conflict changes nothing — no event, no write.
            target = pinned["event_id"]
            if target > len(events):
                return 409, {"error": "checkpoint_conflict"}
            head_hash = (
                events[target - 1]["event_hash"] if target else audit.ZERO_HASH
            )
            if head_hash != pinned["event_hash"]:
                return 409, {"error": "checkpoint_conflict"}
            total = target
            checkpoint = pinned
            checkpoint_auth = self.store.sign_checkpoint_for(pinned)
        else:

        else:
            total = len(events)
            checkpoint = dict(self.store.audit_checkpoint)
            # One fresh signature over the current head on every request;
            # every page fetched in the same export binds the identical
            # checkpoint and therefore the same verifiable envelope.
            checkpoint_auth = self.store.sign_checkpoint()
        if cursor > total:
            return 400, {"error": "cursor is beyond the result set"}
        # Bound the slice by the (possibly pinned) total, not just the
        # log length: a pinned page never returns events past its prefix.
        page = [
            dict(event)
            for event in events[cursor : min(cursor + limit, total)]
        ]
        # The anchor is the predecessor hash of the page's first event;
        # for an empty terminal page it is the (possibly pinned) log
        # head, which the offline verifier requires the last page to meet.
        if cursor == 0:
            anchor_hash = audit.ZERO_HASH
        else:
            anchor_hash = events[cursor - 1]["event_hash"]
        next_cursor = cursor + limit if cursor + limit < total else None
        body = {
            "items": page,
            "total": total,
            "next_cursor": next_cursor,
            "anchor_hash": anchor_hash,
            "checkpoint": checkpoint,
            "checkpoint_auth": checkpoint_auth,
        }
    return 200, body

