_HISTORY_STATUS = {
    "input": 400,
    "auth": 403,
    "state": 409,
    "io": 500,
}

@classmethod
def _history_failure(cls, result: dict) -> tuple[int, dict]:
    category = result.get("error", "io")
    return (
        cls._HISTORY_STATUS.get(category, 500),
        {"ok": False, "error": category},
    )

